const items = $input.all();
const invoices = (items[0] && items[0].json && items[0].json.data) ? items[0].json.data : [];
const now = Math.floor(Date.now() / 1000);
const results = [];

for (const inv of invoices) {
  if (!inv.due_date || inv.paid || inv.status !== 'open') continue;
  const diffDays = Math.floor((now - inv.due_date) / (86400));

  // Strict reminder ladder: ONLY act on exactly day 3, 7, 14, or 30
  let stage = null;
  if (diffDays === 3) stage = 'day3';
  else if (diffDays === 7) stage = 'day7';
  else if (diffDays === 14) stage = 'day14';
  else if (diffDays === 30) stage = 'day30';

  if (stage) {
    results.push({
      json: {
        invoiceId: inv.id,
        invoiceNumber: inv.number,
        customerName: inv.customer_name || 'Valued Customer',
        customerEmail: inv.customer_email,
        amountDue: (inv.amount_due / 100).toFixed(2),
        currency: (inv.currency || 'usd').toUpperCase(),
        hostedInvoiceUrl: inv.hosted_invoice_url,
        daysOverdue: diffDays,
        stage: stage
      }
    });
  }
}

return results;

const item = $input.item.json;
const subject = `Friendly reminder: Invoice ${item.invoiceNumber} is due`;
const body = `Hi ${item.customerName},\n\nHope you are having a productive week.\n\nJust a quick note that invoice ${item.invoiceNumber} for ${item.currency} ${item.amountDue} was due a few days ago. You can review and settle it securely here:\n${item.hostedInvoiceUrl}\n\nIf you have already sent payment, please disregard this note.\n\nBest regards,`;

return {
  json: {
    ...item,
    action: 'send_email',
    subject,
    body
  }
};

const item = $input.item.json;
const subject = `Follow-up: Overdue invoice ${item.invoiceNumber}`;
const body = `Hi ${item.customerName},\n\nChecking in regarding invoice ${item.invoiceNumber} (${item.currency} ${item.amountDue}), which is now 7 days past due.\n\nPlease take a moment to complete payment via the link below:\n${item.hostedInvoiceUrl}\n\nLet us know if you have questions or need us to update billing details.\n\nBest regards,`;

return {
  json: {
    ...item,
    action: 'send_email',
    subject,
    body
  }
};

const item = $input.item.json;
const subject = `Urgent: Invoice ${item.invoiceNumber} is 14 days overdue`;
const body = `Dear ${item.customerName},\n\nWe have not yet received payment for invoice ${item.invoiceNumber} (${item.currency} ${item.amountDue}), due 14 days ago.\n\nPlease process payment today to avoid service interruptions:\n${item.hostedInvoiceUrl}\n\nThank you for your prompt attention.`;

return {
  json: {
    ...item,
    action: 'send_email',
    subject,
    body
  }
};

const item = $input.item.json;
// 30 days is kept for human review rather than sending an automated cold legal notice
const text = `🚨 *30-Day Overdue Invoice Attention Required*\n• *Customer:* ${item.customerName} (${item.customerEmail})\n• *Invoice:* ${item.invoiceNumber} (${item.currency} ${item.amountDue})\n• *Overdue:* 30 days\n• *Review Link:* ${item.hostedInvoiceUrl}\n\n*Action:* No email sent automatically. Please review account relationship.`;

return {
  json: {
    ...item,
    action: 'notify_admin_only',
    slackText: text
  }
};
